<?php
declare(strict_types=1);
namespace DigiForge\Tests;
use DigiForge\POD\CommercialWorksheet;
use PHPUnit\Framework\TestCase;
require_once __DIR__.'/../fixtures/product-packages/CommercialWorksheetFixture.php';
if(is_file(__DIR__.'/../../includes/POD/CommercialWorksheet.php'))require_once __DIR__.'/../../includes/POD/CommercialWorksheet.php';
final class CommercialWorksheetTest extends TestCase {
 public function testSeparatesShippingRevenueAndTaxFromFulfillmentAndFees():void {
  self::assertTrue(class_exists(CommercialWorksheet::class),'A separate source-linked integer commercial worksheet is missing.');
  $i=\CommercialWorksheetFixture::input();$r=CommercialWorksheet::assess($i,$i['binding']);
  self::assertSame(2528,$r['conditional']['gross_revenue_minor']);self::assertSame(165,$r['conditional']['transaction_fee_minor']);self::assertSame(167,$r['conditional']['processing_fee_minor']);self::assertSame(76,$r['conditional']['refund_reserve_minor']);self::assertSame(772,$r['conditional']['contribution_minor']);self::assertNull($r['actual_contribution_minor']);self::assertNull($r['minimum_approved_selling_price_minor']);self::assertFalse($r['commercial_approved']);self::assertFalse($r['external_execution_authorized']);
 }
 public function testUnknownCostNeverBecomesZeroOrProfit():void{$i=\CommercialWorksheetFixture::input();$i['costs']['base_cost_minor']=['value'=>null,'source'=>null];$r=CommercialWorksheet::assess($i,$i['binding']);self::assertNull($r['conditional']['contribution_minor']);self::assertNull($r['conditional']['minimum_modeled_item_price_minor']);self::assertContains('UNKNOWN:base_cost_minor',$r['blockers']);}
 public function testExpiredEvidenceDoesNotProduceMargin():void{$i=\CommercialWorksheetFixture::input();$i['sources']['synthetic']['valid_until']='2026-11-14T11:59:59Z';$r=CommercialWorksheet::assess($i,$i['binding']);self::assertNull($r['conditional']['contribution_minor']);self::assertContains('STALE_SOURCE:synthetic',$r['blockers']);}
 public function testDiscountAndAdsUseActualModeledGrossAndMinimumIsMinimal():void{
  $i=\CommercialWorksheetFixture::input();$i['rates']['discount_bps']['value']=1000;$i['rates']['ads_bps']['value']=1500;$r=CommercialWorksheet::assess($i,$i['binding']);self::assertSame(1619,$r['conditional']['discounted_item_minor']);self::assertSame(2348,$r['conditional']['gross_revenue_minor']);self::assertSame(353,$r['conditional']['ads_fee_minor']);$min=$r['conditional']['minimum_modeled_item_price_minor'];self::assertIsInt($min);$i['revenue']['item_price_minor']['value']=$min;$at=CommercialWorksheet::assess($i,$i['binding'])['conditional'];self::assertGreaterThanOrEqual($at['gross_revenue_minor']*2000,$at['contribution_minor']*10000);$i['revenue']['item_price_minor']['value']=$min-1;$below=CommercialWorksheet::assess($i,$i['binding'])['conditional'];self::assertLessThan($below['gross_revenue_minor']*2000,$below['contribution_minor']*10000);
 }
 public function testIdentityOrAssumptionChangeChangesDigest():void{$i=\CommercialWorksheetFixture::input();$r=CommercialWorksheet::assess($i,$i['binding']);$i['costs']['conversion_minor']['value']=51;$changed=CommercialWorksheet::assess($i,$i['binding']);self::assertNotSame($r['input_sha256'],$changed['input_sha256']);$i['binding']['artwork_sha256']=str_repeat('c',64);$this->expectException(\InvalidArgumentException::class);CommercialWorksheet::assess($i,$r['binding']);}
 public function testZeroFixedCostBreakEvenAtOneHundredPercentFeeIsNotDeclaredImpossible():void{$i=\CommercialWorksheetFixture::input();foreach($i['costs']as &$n)$n['value']=0;unset($n);$i['revenue']['buyer_tax_minor']['value']=0;$i['revenue']['buyer_shipping_minor']['value']=0;foreach($i['rates']as &$n)$n['value']=0;unset($n);$i['rates']['transaction_bps']['value']=10000;$i['target_margin_bps']=0;$r=CommercialWorksheet::assess($i,$i['binding']);self::assertSame(1,$r['conditional']['minimum_modeled_item_price_minor']);}
 public function testMinimumMatchesBruteForceDespiteFeeRoundingDips():void{$i=\CommercialWorksheetFixture::input();$i['rates']['discount_bps']['value']=1700;$i['rates']['ads_bps']['value']=1200;$i['rates']['processing_bps']['value']=499;$min=CommercialWorksheet::assess($i,$i['binding'])['conditional']['minimum_modeled_item_price_minor'];$first=null;for($price=1;$price<5000;$price++){$net=intdiv($price*8300,10000)+729;$fee=static fn($base,$rate)=>intdiv($base*$rate+9999,10000);$profit=$net-1378-$fee($net,650)-$fee($net+200,499)-$fee($net,1200)-$fee($net,300);if($net>0&&$profit*10000>=$net*2000){$first=$price;break;}}self::assertSame($first,$min);}
 public static function malformed():array{return [['null_byte_date'],['nested_source_auth_query'],['source_auth_query'],['binding_authority'],['binding_variant_type'],['float'],['bool'],['negative'],['foreign_shop'],['source_missing'],['future_source'],['duplicate_fx'],['wrong_currency'],['forged_approval'],['bad_date'],['unbounded_rate']];}
 /** @dataProvider malformed */
 public function testMalformedAndUntrustedClaimsDeny(string $case):void{$i=\CommercialWorksheetFixture::input();$binding=$i['binding'];switch($case){case'null_byte_date':$i['as_of']="2026-11-14T12:00:00Z\0";break;case'nested_source_auth_query':$i['sources']['synthetic']['reference']='https://example.invalid/evidence?q[access_token]=do-not-export';break;case'source_auth_query':$i['sources']['synthetic']['reference']='https://example.invalid/evidence?access_token=do-not-export';break;case'binding_authority':$i['binding']['allocation_verified']=true;$binding=$i['binding'];break;case'binding_variant_type':$i['binding']['variant_ids']=[true];$binding=$i['binding'];break;case'float':$i['costs']['base_cost_minor']['value']=5.09;break;case'bool':$i['rates']['ads_bps']['value']=false;break;case'negative':$i['costs']['other_cost_minor']['value']=-1;break;case'foreign_shop':$i['binding']['shop_key']='digital';break;case'source_missing':$i['costs']['base_cost_minor']['source']='missing';break;case'future_source':$i['sources']['synthetic']['observed_at']='2027-01-01';break;case'duplicate_fx':$i['costs']['payoneer_minor']=['value'=>100,'source'=>'synthetic'];break;case'wrong_currency':$i['currency']='INR';break;case'forged_approval':$i['commercial_approved']=true;break;case'bad_date':$i['as_of']='2026-02-30T00:00:00Z';break;case'unbounded_rate':$i['rates']['processing_bps']['value']=10001;break;}$this->expectException(\InvalidArgumentException::class);CommercialWorksheet::assess($i,$binding);}
}
